using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;
[InitializeOnLoad]public static class FinalCitySignTemplates{
static FinalCitySignTemplates(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalCitySignTemplates.request")||EditorApplication.isCompiling)return;File.Delete("FinalCitySignTemplates.request");try{string dir="Assets/Scenes/Oasis/CityBuildingSigns";Directory.CreateDirectory(dir+"/Templates");var t=typeof(FinalCitySigns);var st=t.GetNestedType("Site",BindingFlags.NonPublic);var bt=t.GetNestedType("B",BindingFlags.NonPublic);var mat=AssetDatabase.LoadAssetAtPath<Material>(dir+"/City Shared Sign Atlas.mat");string[] names={"VELOCITY","AURA","PLAY NEXT","HARVEST","MIRAGE","NOVA BOT","STRIDE","FIRE SLICE","PULSE","SKYLINE","ORBIT","MIRAGE THREADS","TECH LAB","HOTEL","GAME ZONE","STAY","OASIS","ARCADE","DINER","NOVA","SKYLINE LOGO","PEAK","OASIS CAFE","SYNERGY"};int total=0;for(int i=0;i<24;i++){var site=Activator.CreateInstance(st,true);st.GetField("p").SetValue(site,Vector3.zero);st.GetField("n").SetValue(site,Vector3.forward);st.GetField("w").SetValue(site,i<12?10f:i<20?1.55f:3f);st.GetField("h").SetValue(site,i<12?10f/1.8f:i<20?4.5f:3f);st.GetField("art").SetValue(site,i);var b=Activator.CreateInstance(bt,true);bt.GetMethod("Board").Invoke(b,new object[]{site,i>=12});var mesh=(Mesh)bt.GetMethod("Mesh").Invoke(b,new object[]{"Sign "+names[i],Vector3.zero});var uv=mesh.uv;var colors=mesh.colors;for(int j=0;j<mesh.vertexCount;j+=4){if(colors[j].a<.4||colors[j].a>.6)continue;float sum=uv[j].x+uv[j+2].x;for(int k=j;k<j+4;k++)uv[k].x=sum-uv[k].x;}mesh.uv=uv;string path=dir+"/Templates/Sign "+i.ToString("00")+" "+names[i]+".asset";if(AssetDatabase.LoadAssetAtPath<Mesh>(path)){UnityEngine.Object.DestroyImmediate(mesh);continue;}AssetDatabase.CreateAsset(mesh,path);var go=new GameObject("Sign "+names[i]);go.AddComponent<MeshFilter>().sharedMesh=mesh;var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.Off;r.receiveShadows=false;r.lightProbeUsage=LightProbeUsage.Off;var lod=go.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.035f,new Renderer[]{r})});lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(go,dir+"/Templates/Sign "+i.ToString("00")+" "+names[i]+".prefab");UnityEngine.Object.DestroyImmediate(go);total++;}AssetDatabase.SaveAssets();File.WriteAllText("FinalEnvironmentRoadReview/CitySignTemplatesReport.txt","SUCCESS 24 reusable individual sign prefabs: 12 wide, 8 tall, 4 logos; same single atlas/material; no lights/colliders");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CitySignTemplatesReport.txt","FAILED "+e);Debug.LogException(e);}}}
